package org.rustlanglatam.zeroclaw.android

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.net.Uri

/**
 * Plays the assistant's notification sound (`res/raw/ksandra_chime.wav`, generated by `scripts/chime.py`) and creates
 * notification channels that use it.
 */
object Chime {

    private val attributes = AudioAttributes.Builder()
        .setUsage(AudioAttributes.USAGE_NOTIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()

    private fun uri(context: Context) = Uri.parse("android.resource://${context.packageName}/${R.raw.ksandra_chime}")

    /** Plays the chime once with notification audio attributes, so it follows the phone's silent mode. */
    fun play(context: Context) {
        runCatching {
            MediaPlayer().apply {
                setAudioAttributes(attributes)
                setDataSource(context.applicationContext, uri(context))
                setOnCompletionListener { it.release() }
                prepare()
                start()
            }
        }
    }

    /**
     * Creates a notification channel that plays the chime and returns its id. A channel's sound cannot be changed after
     * creation, so the channel uses the id suffixed with `-k` and the legacy channel [id] is deleted.
     */
    fun channel(context: Context, id: String, name: String, importance: Int): String {
        val manager = context.getSystemService(NotificationManager::class.java)
        manager.deleteNotificationChannel(id)
        manager.createNotificationChannel(NotificationChannel("$id-k", name, importance).apply { setSound(uri(context), attributes) })
        return "$id-k"
    }
}
